-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 41 recettes, 14 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', 'Wikimedia Commons', ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · Wikimedia Commons',
        true, true, 'Photo Wikimedia Commons vérifiée : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"civet-de-senglar","country":"AD","original":"Civet de senglar","title":"Civet de senglar andorran (sanglier mijoté au vin rouge)","en":"Andorran civet de senglar (wild boar stew in red wine)","es":"Civet de senglar andorrano (jabalí guisado al vino tinto)","desc":"Sanglier mariné au vin rouge et aux herbes des Pyrénées, mijoté longuement avec chocolat noir et champignons, plat d’automne andorran.","cat":"Ragoût","diff":"medium","prep":30,"cook":150,"serv":6,"ing":[["Sanglier",1.2,"kg","en cubes"],["Vin rouge",750,"ml",null],["Oignons",2,null,"hachés"],["Carottes",2,null,"en rondelles"],["Ail",4,"gousses",null],["Thym et laurier",1,"bouquet",null],["Chocolat noir",20,"g",null],["Champignons des bois",250,"g",null],["Farine",2,"c. à soupe",null],["Huile d’olive",4,"c. à soupe",null],["Sel et poivre",2,"c. à thé",null]],"steps":["Mariner la viande dans le vin avec oignons, carottes, ail et herbes pendant 24 heures.","Égoutter la viande, la sécher, la fariner et la dorer dans l’huile.","Ajouter les légumes de la marinade puis le vin filtré.","Mijoter 2 heures à couvert.","Ajouter le chocolat et les champignons sautés; cuire 20 minutes et servir."],"photo":null},{"slug":"truita-de-carreroles","country":"AD","original":"Truita de carreroles","title":"Truita de carreroles andorrane (omelette aux mousserons)","en":"Andorran truita de carreroles (fairy ring mushroom omelette)","es":"Truita de carreroles andorrana (tortilla de senderuelas)","desc":"Omelette épaisse aux mousserons des prés (carreroles), ail et persil, cueillis au printemps dans les montagnes andorranes.","cat":"Plat principal","diff":"easy","prep":10,"cook":15,"serv":4,"ing":[["Mousserons ou champignons des bois",300,"g","nettoyés"],["Œufs",6,null,null],["Ail",2,"gousses","hachées"],["Persil",1,"poignée","haché"],["Huile d’olive",3,"c. à soupe",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Faire sauter les champignons dans l’huile avec l’ail jusqu’à évaporation de leur eau.","Battre les œufs avec persil, sel et poivre.","Verser les œufs sur les champignons.","Cuire à feu doux, retourner à l’aide d’une assiette et cuire l’autre face.","Servir chaud ou tiède."],"photo":null},{"slug":"cargols-a-la-llauna","country":"AD","original":"Cargols a la llauna","title":"Cargols a la llauna andorrans (escargots grillés, allioli)","en":"Andorran cargols a la llauna (grilled snails with allioli)","es":"Cargols a la llauna andorranos (caracoles a la lata con alioli)","desc":"Escargots grillés sur une plaque en fer (llauna) avec sel, poivre et herbes, servis avec allioli, tradition des montagnes catalanes et andorranes.","cat":"Entrée","diff":"medium","prep":30,"cook":20,"serv":4,"ing":[["Escargots vivants dégorgés ou précuits",1,"kg",null],["Gros sel",2,"c. à soupe",null],["Poivre",1,"c. à thé",null],["Thym",1,"c. à thé",null],["Huile d’olive",80,"ml",null],["Ail",4,"gousses","pour l’allioli"],["Huile d’olive (allioli)",200,"ml",null]],"steps":["Laver les escargots et les disposer ouverture vers le haut sur une plaque.","Saupoudrer de gros sel, poivre et thym.","Griller 15 à 20 minutes sous le gril ou sur braise, en arrosant d’huile en fin de cuisson.","Piler l’ail avec une pincée de sel, puis monter à l’huile goutte à goutte pour l’allioli.","Servir les escargots brûlants avec l’allioli."],"photo":null},{"slug":"cevapi-sarajevo","country":"BA","place":"ba-sarajevo","original":"Ćevapi (Sarajevski ćevapi)","title":"Ćevapi de Sarajevo (petites saucisses grillées dans le somun)","en":"Sarajevo ćevapi (grilled minced meat in somun bread)","es":"Ćevapi de Sarajevo (carne picada a la parrilla en pan somun)","desc":"Petits rouleaux de bœuf haché grillés, servis par dix dans un pain somun avec oignon cru et kajmak, fierté de Baščaršija à Sarajevo.","cat":"Grillade","diff":"easy","prep":20,"cook":15,"serv":4,"ing":[["Bœuf haché",800,"g",null],["Agneau haché",200,"g","facultatif"],["Bicarbonate de soude",0.5,"c. à thé",null],["Eau gazeuse",100,"ml",null],["Sel et poivre",2,"c. à thé",null],["Pains somun ou pitas épaisses",4,null,null],["Oignon",1,null,"haché"],["Kajmak ou crème épaisse",150,"g",null]],"steps":["Pétrir la viande avec le bicarbonate, l’eau gazeuse, le sel et le poivre; réfrigérer une nuit.","Former des petits rouleaux de 6 cm.","Griller 8 à 10 minutes sur braise en retournant.","Réchauffer le pain sur le gril.","Servir 10 ćevapi par pain avec oignon cru et kajmak."],"photo":null},{"slug":"bosanski-lonac","country":"BA","original":"Bosanski lonac","title":"Bosanski lonac (pot-au-feu bosnien de viandes et légumes)","en":"Bosanski lonac (Bosnian meat and vegetable pot)","es":"Bosanski lonac (olla bosnia de carnes y verduras)","desc":"Viandes et légumes disposés en couches dans un pot de terre et cuits très lentement dans leur jus, plat national bosnien.","cat":"Ragoût","diff":"easy","prep":30,"cook":180,"serv":6,"ing":[["Bœuf et agneau",1,"kg","en gros cubes"],["Chou",0.5,null,"en morceaux"],["Pommes de terre",4,null,"en quartiers"],["Carottes",2,null,null],["Poivrons",2,null,null],["Tomates",3,null,null],["Oignons",2,null,null],["Ail",1,"tête",null],["Grains de poivre et laurier",1,"c. à thé",null],["Sel",2,"c. à thé",null]],"steps":["Alterner dans un pot de terre ou une cocotte couches de viande et de légumes.","Glisser l’ail, le poivre et le laurier entre les couches; saler.","Ajouter de l’eau à mi-hauteur.","Couvrir hermétiquement et cuire 3 heures au four à 160 °C.","Servir dans le pot avec du pain."],"photo":null},{"slug":"tufahija","country":"BA","original":"Tufahija","title":"Tufahija bosnienne (pommes pochées farcies aux noix)","en":"Bosnian tufahija (walnut-stuffed poached apples)","es":"Tufahija bosnia (manzanas escalfadas rellenas de nuez)","desc":"Pommes pochées dans un sirop, farcies de noix et nappées de crème fouettée, dessert d’origine ottomane très apprécié en Bosnie.","cat":"Dessert","diff":"easy","prep":20,"cook":20,"serv":6,"ing":[["Pommes fermes",6,null,"pelées et évidées"],["Sucre",300,"g",null],["Eau",1,"l",null],["Citron",1,null,"jus"],["Noix",150,"g","moulues"],["Sucre (farce)",50,"g",null],["Crème fouettée",200,"ml",null]],"steps":["Porter l’eau, le sucre et le citron à ébullition.","Pocher les pommes 8 à 10 minutes jusqu’à ce qu’elles soient tendres mais fermes.","Mélanger noix, sucre et quelques cuillerées de sirop.","Farcir les pommes refroidies.","Servir nappées de sirop réduit et de crème fouettée."],"photo":null},{"slug":"waterzooi-gantois","country":"BE","place":{"slug":"be-gand","name":"Gand","type":"city","lat":51.0543,"lng":3.7174,"summary":"Ville flamande historique, berceau du waterzooi."},"original":"Gentse waterzooi","title":"Waterzooi gantois (poulet et légumes dans un bouillon crémeux)","en":"Ghent waterzooi (creamy chicken and vegetable stew)","es":"Waterzooi de Gante (pollo y verduras en caldo cremoso)","desc":"Poulet poché avec poireaux, carottes et céleri dans un bouillon lié à la crème et au jaune d’œuf, spécialité de Gand.","cat":"Soupe","diff":"easy","prep":20,"cook":60,"serv":4,"ing":[["Poulet",1.5,"kg","en morceaux"],["Poireaux",2,null,"en julienne"],["Carottes",3,null,"en julienne"],["Céleri branche",3,"branches","en julienne"],["Pommes de terre",4,null,"en dés"],["Bouillon de volaille",1.5,"l",null],["Crème",200,"ml",null],["Jaunes d’œufs",2,null,null],["Persil",1,"poignée",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Pocher le poulet dans le bouillon 40 minutes; le retirer et l’effilocher.","Cuire les légumes dans le bouillon 15 minutes.","Mélanger crème et jaunes, les incorporer hors du feu.","Remettre le poulet et chauffer sans bouillir.","Servir en assiettes creuses avec du persil."],"photo":null},{"slug":"gaufres-de-liege","country":"BE","place":{"slug":"be-liege","name":"Liège","type":"city","lat":50.6326,"lng":5.5797,"summary":"Ville wallonne sur la Meuse, patrie de la gaufre au sucre perlé et des boulets."},"original":"Gaufre de Liège","title":"Gaufres de Liège (pâte levée au sucre perlé caramélisé)","en":"Liège waffles (pearl sugar yeast waffles)","es":"Gofres de Lieja (masa fermentada con azúcar perlado)","desc":"Gaufres denses à la pâte briochée, parsemées de sucre perlé qui caramélise à la cuisson, spécialité de Liège.","cat":"Dessert","diff":"medium","prep":30,"cook":20,"serv":10,"ing":[["Farine",500,"g",null],["Lait tiède",150,"ml",null],["Levure sèche",10,"g",null],["Œufs",3,null,null],["Beurre mou",250,"g",null],["Sucre vanillé",1,"sachet",null],["Sucre perlé",200,"g",null],["Sel",1,"pincée",null]],"steps":["Pétrir farine, lait, levure, œufs et sel; laisser lever 45 minutes.","Incorporer le beurre mou et le sucre vanillé en pétrissant.","Ajouter le sucre perlé et laisser reposer 15 minutes.","Former des boules de 80 g.","Cuire 3 à 4 minutes dans un gaufrier à gros carreaux jusqu’à caramélisation."],"photo":null},{"slug":"stoemp-bruxellois","country":"BE","place":"be-brussels","original":"Stoemp","title":"Stoemp bruxellois (purée de pommes de terre et légumes, saucisse)","en":"Brussels stoemp (potato and vegetable mash with sausage)","es":"Stoemp de Bruselas (puré de patata y verduras con salchicha)","desc":"Purée rustique de pommes de terre écrasées avec carottes, poireaux ou chou de Bruxelles, servie avec saucisse et lard.","cat":"Plat principal","diff":"easy","prep":20,"cook":30,"serv":4,"ing":[["Pommes de terre",1,"kg",null],["Carottes",400,"g",null],["Poireau",1,null,null],["Beurre",50,"g",null],["Lait",100,"ml",null],["Muscade",1,"pincée",null],["Saucisses",4,null,null],["Lard",4,"tranches",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Cuire pommes de terre et carottes à l’eau salée.","Faire fondre le poireau émincé au beurre.","Écraser grossièrement les légumes avec le poireau, le lait et la muscade.","Poêler saucisses et lard.","Servir le stoemp avec la viande et son jus."],"photo":null},{"slug":"zurcher-geschnetzeltes","country":"CH","place":{"slug":"ch-zurich","name":"Zurich","type":"city","lat":47.3769,"lng":8.5417,"summary":"Plus grande ville suisse, patrie du Zürcher Geschnetzeltes et du birchermüesli."},"original":"Zürcher Geschnetzeltes","title":"Émincé de veau à la zurichoise (sauce crème et champignons)","en":"Zürcher Geschnetzeltes (Zurich-style veal in cream sauce)","es":"Zürcher Geschnetzeltes (ternera a la zuriquesa en salsa de nata)","desc":"Fines lanières de veau saisies puis nappées d’une sauce au vin blanc, crème et champignons, servies avec des röstis.","cat":"Plat principal","diff":"easy","prep":15,"cook":20,"serv":4,"ing":[["Veau (noix)",600,"g","en fines lanières"],["Champignons de Paris",250,"g","émincés"],["Échalotes",2,null,"hachées"],["Vin blanc sec",150,"ml",null],["Fond de veau",100,"ml",null],["Crème",200,"ml",null],["Beurre",30,"g",null],["Farine",1,"c. à soupe",null],["Persil",1,"poignée",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Fariner légèrement le veau et le saisir très rapidement au beurre; réserver.","Faire revenir échalotes et champignons.","Déglacer au vin blanc, ajouter le fond et réduire de moitié.","Ajouter la crème et réduire jusqu’à nappe.","Remettre le veau juste pour le réchauffer, parsemer de persil et servir avec des röstis."],"photo":null},{"slug":"raclette-valais","country":"CH","place":{"slug":"ch-valais","name":"Valais","type":"region","lat":46.19,"lng":7.6,"summary":"Canton alpin du sud-ouest suisse, berceau de la raclette AOP."},"original":"Raclette du Valais","title":"Raclette du Valais (fromage fondu, pommes de terre et cornichons)","en":"Valais raclette (melted cheese with potatoes)","es":"Raclette del Valais (queso fundido con patatas)","desc":"Fromage à raclette fondu et raclé sur des pommes de terre en robe des champs, servi avec cornichons et petits oignons, tradition valaisanne.","cat":"Plat principal","diff":"easy","prep":10,"cook":25,"serv":4,"ing":[["Fromage à raclette du Valais",1,"kg",null],["Pommes de terre à chair ferme",1.2,"kg",null],["Cornichons",150,"g",null],["Petits oignons au vinaigre",150,"g",null],["Poivre et paprika",1,"c. à thé",null]],"steps":["Cuire les pommes de terre en robe des champs à l’eau salée.","Faire fondre le fromage sous un appareil à raclette ou au four.","Racler le fromage fondu sur les pommes de terre.","Assaisonner de poivre et paprika.","Servir avec cornichons, oignons et un vin blanc du Valais."],"photo":null},{"slug":"engadiner-nusstorte","country":"CH","place":{"slug":"ch-engadine","name":"Engadine","type":"region","lat":46.62,"lng":9.95,"summary":"Haute vallée des Grisons, célèbre pour sa tourte aux noix."},"original":"Engadiner Nusstorte","title":"Tourte aux noix de l’Engadine (caramel et noix sous pâte sablée)","en":"Engadine walnut tart (Engadiner Nusstorte)","es":"Tarta de nueces de Engadina (caramelo y nueces)","desc":"Pâte sablée renfermant une garniture de noix caramélisées à la crème, spécialité des confiseurs grisons de l’Engadine.","cat":"Dessert","diff":"medium","prep":40,"cook":40,"serv":10,"ing":[["Farine",350,"g",null],["Beurre",200,"g",null],["Sucre (pâte)",120,"g",null],["Œuf",1,null,null],["Sucre (caramel)",250,"g",null],["Crème",200,"ml",null],["Noix",300,"g","concassées"],["Miel",1,"c. à soupe",null]],"steps":["Sabler farine, beurre et sucre, ajouter l’œuf; reposer au frais 1 heure.","Caraméliser le sucre à sec, déglacer avec la crème chaude, ajouter noix et miel; laisser tiédir.","Foncer un moule avec les deux tiers de la pâte et verser la garniture.","Couvrir avec le reste de pâte, souder et piquer.","Cuire 40 minutes à 180 °C et laisser refroidir complètement avant de couper."],"photo":null},{"slug":"zagorski-strukli","country":"HR","place":{"slug":"hr-zagorje","name":"Hrvatsko zagorje","type":"region","lat":46.1,"lng":15.9,"summary":"Région de collines au nord de Zagreb, berceau des štrukli."},"original":"Zagorski štrukli","title":"Štrukli du Zagorje (pâte fine au fromage frais gratinée)","en":"Zagorje štrukli (cheese-filled pastry)","es":"Štrukli de Zagorje (masa fina rellena de queso)","desc":"Rouleaux de pâte très fine garnis de fromage frais et de crème, pochés ou gratinés au four, patrimoine culinaire croate reconnu.","cat":"Plat principal","diff":"hard","prep":60,"cook":40,"serv":6,"ing":[["Farine",400,"g",null],["Eau tiède",200,"ml",null],["Huile",3,"c. à soupe",null],["Fromage frais (cottage ou ricotta)",600,"g",null],["Œufs",3,null,null],["Crème aigre",200,"g",null],["Crème liquide",200,"ml","pour gratiner"],["Beurre",50,"g",null],["Sel",1,"c. à thé",null]],"steps":["Pétrir farine, eau, huile et sel; laisser reposer 1 heure sous un bol chaud.","Mélanger fromage, œufs, crème aigre et sel.","Étirer la pâte sur une nappe farinée jusqu’à ce qu’elle soit transparente.","Répartir la farce, rouler avec la nappe et couper en tronçons en pressant avec le bord d’une assiette.","Disposer dans un plat beurré, napper de crème et cuire 35 à 40 minutes à 200 °C."],"photo":null},{"slug":"peka-dalmate","country":"HR","place":"hr-dalmatia","original":"Peka","title":"Peka dalmate (agneau et pommes de terre sous cloche)","en":"Dalmatian peka (lamb and potatoes under the bell)","es":"Peka dálmata (cordero y patatas bajo campana)","desc":"Agneau ou poulpe cuit avec pommes de terre et romarin sous une cloche en fer recouverte de braises, grand classique dalmate.","cat":"Plat principal","diff":"medium","prep":20,"cook":150,"serv":6,"ing":[["Épaule d’agneau",1.5,"kg","en morceaux"],["Pommes de terre",1.2,"kg","en quartiers"],["Oignons",2,null,"en quartiers"],["Ail",6,"gousses",null],["Romarin",4,"branches",null],["Vin blanc",200,"ml",null],["Huile d’olive",100,"ml",null],["Sel et poivre",2,"c. à thé",null]],"steps":["Mettre viande, pommes de terre, oignons, ail et romarin dans une cocotte en fonte.","Arroser d’huile et de vin; saler et poivrer.","Couvrir hermétiquement.","Cuire 2 heures à 180 °C (ou sous cloche recouverte de braises).","Découvrir 20 minutes pour dorer et servir."],"photo":null},{"slug":"fritule-croates","country":"HR","original":"Fritule","title":"Fritule croates (pe