:null},{"slug":"buzara-boka","country":"ME","place":{"slug":"me-boka-kotorska","name":"Bouches de Kotor","type":"region","lat":42.45,"lng":18.7,"summary":"Baie adriatique du Monténégro (Kotor, Perast), réputée pour ses moules et la buzara."},"original":"Buzara","title":"Buzara des Bouches de Kotor (moules au vin blanc, ail et chapelure)","en":"Boka Kotorska buzara (mussels in white wine and garlic)","es":"Buzara de las Bocas de Kotor (mejillones al vino blanco y ajo)","desc":"Moules ou langoustines cuites au vin blanc, ail, persil et chapelure, spécialité des Bouches de Kotor.","cat":"Fruits de mer","diff":"easy","prep":15,"cook":15,"serv":4,"ing":[["Moules",1.5,"kg","nettoyées"],["Vin blanc",200,"ml",null],["Ail",5,"gousses","hachées"],["Persil",1,"bouquet","haché"],["Chapelure",3,"c. à soupe",null],["Huile d’olive",5,"c. à soupe",null],["Tomate",1,null,"râpée, facultatif"],["Poivre",0.5,"c. à thé",null]],"steps":["Faire revenir l’ail dans l’huile.","Ajouter les moules, le vin et la tomate; couvrir.","Cuire 5 minutes en secouant jusqu’à ce qu’elles s’ouvrent.","Ajouter persil et chapelure pour lier la sauce; cuire 2 minutes.","Servir avec du pain pour la sauce."],"photo":null},{"slug":"njeguski-raznjic","country":"ME","place":"njegusi","original":"Njeguški ražanj","title":"Njeguški ražanj (rôti de porc farci au jambon de Njeguši et fromage)","en":"Njeguši ražanj (pork stuffed with prosciutto and cheese)","es":"Njeguški ražanj (cerdo relleno de jamón de Njeguši y queso)","desc":"Escalopes de porc roulées autour du jambon fumé de Njeguši et du fromage local, rôties — spécialité du village de Njeguši.","cat":"Plat principal","diff":"medium","prep":25,"cook":45,"serv":4,"ing":[["Filet ou échine de porc",800,"g","en escalopes fines"],["Jambon de Njeguši ou prosciutto",150,"g",null],["Fromage de Njeguši ou gouda",150,"g","en bâtonnets"],["Kajmak ou crème épaisse",100,"g",null],["Ail",2,"gousses",null],["Huile",3,"c. à soupe",null],["Sel et poivre",1,"c. à thé",null]],"st