:[["Pain de mie",8,"tranches",null],["Steaks fins",4,null,null],["Jambon cuit",8,"tranches",null],["Linguiça ou saucisses",2,null,"en deux dans la longueur"],["Fromage à fondre",16,"tranches",null],["Bière blonde",330,"ml","pour la sauce"],["Coulis de tomate",300,"ml",null],["Porto ou brandy",3,"c. à soupe",null],["Oignon et ail",1,"portion","hachés"],["Piment en poudre",1,"c. à thé",null],["Œufs",4,null,"au plat, facultatif"]],"steps":["Faire revenir oignon et ail, ajouter bière, coulis, porto et piment; mijoter 30 minutes et mixer.","Cuire steaks et saucisses à la poêle.","Monter chaque sandwich : pain, jambon, steak, saucisse, pain.","Couvrir entièrement de tranches de fromage et gratiner 5 minutes au four.","Napper de sauce brûlante, ajouter un œuf au plat et servir avec des frites."],"photo":null},{"slug":"pljeskavica-leskovac","country":"RS","place":{"slug":"rs-leskovac","name":"Leskovac","type":"city","lat":42.9981,"lng":21.9461,"summary":"Ville du sud de la Serbie, capitale des grillades et de sa célèbre semaine du barbecue."},"original":"Leskovačka pljeskavica","title":"Pljeskavica de Leskovac (galette de viande grillée pimentée)","en":"Leskovac pljeskavica (spicy grilled meat patty)","es":"Pljeskavica de Leskovac (hamburguesa picante a la parrilla)","desc":"Grande galette plate de viandes hachées à l’oignon et au piment, grillée et servie dans une lepinja avec kajmak — spécialité de Leskovac.","cat":"Grillade","diff":"easy","prep":20,"cook":15,"serv":4,"ing":[["Porc et bœuf hachés",800,"g",null],["Oignons",2,null,"hachés fin"],["Piment fort",1,null,"haché"],["Sel et poivre",2,"c. à thé",null],["Eau gazeuse",60,"ml",null],["Lepinja ou pains plats",4,null,null],["Kajmak ou crème épaisse",150,"g",null]],"steps":["Mélanger la viande, la moitié des oignons, le piment, le sel, le poivre et l’eau gazeuse.","Réfrigérer 2 heures.","Former des galettes larges et fines.","Griller 4 à 5 minutes par face.","Servir dans le pain avec kajmak et oignon cru."],"photo":null},{"slug":"karadjordjeva-snicla","country":"RS","place":{"slug":"rs-belgrade","name":"Belgrade","type":"city","lat":44.7866,"lng":20.4489,"summary":"Capitale serbe au confluent de la Save et du Danube, patrie de la Karađorđeva šnicla."},"original":"Karađorđeva šnicla","title":"Karađorđeva šnicla de Belgrade (escalope roulée au kajmak panée)","en":"Belgrade Karađorđeva šnicla (breaded kajmak-stuffed schnitzel)","es":"Karađorđeva šnicla de Belgrado (escalope enrollado relleno de kajmak)","desc":"Escalope de porc ou de veau roulée autour du kajmak, panée et frite, servie avec sauce tartare et citron — créée à Belgrade dans les années 1950.","cat":"Plat principal","diff":"medium","prep":25,"cook":20,"serv":4,"ing":[["Escalopes de porc ou de veau",4,null,"aplaties très finement"],["Kajmak ou fromage frais épais",200,"g",null],["Farine",60,"g",null],["Œufs",2,null,"battus"],["Chapelure",150,"g",null],["Huile",500,"ml","pour la friture"],["Sauce tartare",150,"g",null],["Citron",1,null,null],["Sel et poivre",1,"c. à thé",null]],"steps":["Saler et poivrer les escalopes.","Déposer un boudin de kajmak et rouler serré.","Paner : farine, œuf, chapelure.","Frire 8 à 10 minutes en retournant jusqu’à ce qu’elles soient dorées.","Servir avec frites, sauce tartare et citron."],"photo":null},{"slug":"pasulj","country":"RS","original":"Pasulj","title":"Pasulj serbe (haricots blancs mijotés au lard fumé)","en":"Serbian pasulj (bean stew with smoked meat)","es":"Pasulj serbio (guiso de alubias con carne ahumada)","desc":"Haricots blancs cuits longuement avec viande fumée, oignons et paprika, plat national serbe du vendredi et des cantines.","cat":"Ragoût","diff":"easy","prep":15,"cook":150,"serv":6,"ing":[["Haricots blancs",500,"g","trempés une nuit"],["Travers ou jarret fumé",500,"g",null],["Oignons",2,null,"hachés"],["Carotte",1,null,"en dés"],["Ail",3,"gousses",null],["Paprika",2,"c. à thé",null],["Farine",1,"c. à soupe",null],["Huile",3,"c. à soupe",null],["Laurier",2,"feuilles",null]